package emon;


public final class Ocalibtest {
    public static void testPpWordCalibrationIsMonotoneAtEveryPermille() {
        int i = 0;
        int previous = 0;
        while (i < 1001) {
            int p = Ocalib.ocalWord(2, 0, i);
            emon.Testport.assertThat(p >= previous, "weighted isotonic calibration");
            previous = p;
            i += 1;
        }
    }
    public static void testPpCalibrationFloorsMillionthsAtBinEdges() {
        int edge = 100000;
        while (edge < 1000000) {
            emon.Testport.assertEq(Ocalib.ocalWord(2, 0, (edge - 1) / 1000), Ocalib.ocalWord(2, 0, (edge / 1000) - 1), "below edge");
            emon.Testport.assertEq(Ocalib.ocalWord(2, 0, (edge + 1) / 1000), Ocalib.ocalWord(2, 0, edge / 1000), "above edge");
            edge += 100000;
        }
    }
    public static void testPpInvertedBinsPoolTheOriginalFitObservations() {
        emon.Testport.assertEq(Ocalib.ocalWord(2, 0, 600), 422, "57 correct of 135");
        emon.Testport.assertEq(Ocalib.ocalWord(2, 0, 799), 422, "same pooled bin");
        emon.Testport.assertEq(Ocalib.ocalWord(2, 0, 800), 521, "next frozen bin");
        emon.Testport.assertEq(Ocalib.ocalWord(3, 0, 1000), -1, "unfitted engine is not a zero probability");
    }
}
